// UreTech Email Signature — handler event-based (OnNewMessageCompose + OnMessageFromChanged).
//
// - Firma grafica sotto il testo, automatica, su Outlook web/Win/Mac e mobile.
// - DisplayName + Email: dal vivo (from.getAsync).
// - Title (jobTitle): da Microsoft Graph via NAA (token silenzioso). Fallback morbido:
//   se auth/Graph falliscono, la firma viene comunque inserita col Title vuoto (zero regressione).
// - OnMessageFromChanged: riapplica la firma se l'utente cambia il From (caselle condivise).
// - disableClientSignatureAsync prima di setSignatureAsync per evitare doppioni.
// - marker URE-SIG-v1 nel corpo (per eventuale transport rule di sicurezza).

// Config MSAL per NAA (Nested App Authentication) — INLINE (non importata) di proposito:
// uno `import` statico da "./authconfig" restava nel bundle e, caricato come <script> CLASSICO nel
// runtime webview di OWA, dava `Uncaught SyntaxError: Cannot use import statement outside a module`
// → rompeva il runtime sul WEB (sul desktop gira un runtime diverso, per questo lì funzionava).
// clientId = app "UreTech Signature Add-in"; authority = tenant uretechbusiness (single-tenant).
var auth = {
  clientId: "94b2bf2c-e3a2-4be6-8bd1-afff4bbbb0b5",
  authority: "https://login.microsoftonline.com/baae350f-0bfe-4325-a811-85165da0390c",
};

// NB: MSAL (@azure/msal-browser) NON è importato staticamente: viene caricato con
// import() DINAMICO dentro ure_initPca, SOLO quando serve il titolo (desktop/web).
// Motivo: l'import statico finiva nel bundle principale e poteva far fallire il
// caricamento del runtime nel webview MOBILE → handler non registrati → nessuna firma.
// Con il dynamic import, se MSAL non carica (es. mobile) la firma viene comunque inserita.

/* global Office, console, fetch */

var URE_MARKER = "URE-SIG-v1";

function ure_isValid(s) {
  return s !== null && s !== undefined && s !== "";
}

// Firma grafica completa con campi dinamici (Title passato come parametro).
