// ---- Microsoft Graph via NAA (per il jobTitle) ----
var ure_pca = undefined;
var ure_pcaReady = false;

async function ure_initPca() {
  if (ure_pcaReady) return;
  // import() dinamico: MSAL caricato a richiesta, fuori dal bundle critico.
  var msal = await import("@azure/msal-browser");
  ure_pca = await msal.createNestablePublicClientApplication({ auth: auth });
  ure_pcaReady = true;
}

// Restituisce { displayName, title } del mittente da Graph. Può lanciare (gestito dal chiamante).
// NB: per le CASELLE CONDIVISE il displayName di Graph è quello giusto (es. "Amministrazione UreTech"),
// mentre from.getAsync restituisce il nome del DELEGATO → per questo Graph è la fonte primaria del nome.
async function ure_getProfile(email) {
  await ure_initPca();
  var result = await ure_pca.acquireTokenSilent({ scopes: ["User.Read.All"] });
  var token = result && result.accessToken;
  if (!token) throw new Error("no access token");
  var url = "https://graph.microsoft.com/v1.0/users/" + encodeURIComponent(email) + "?$select=displayName,jobTitle";
  var resp = await fetch(url, { headers: { Authorization: "Bearer " + token } });
  if (!resp.ok) throw new Error("graph " + resp.status);
  var data = await resp.json();
  return {
    displayName: (data && data.displayName) ? data.displayName : "",
    title: (data && data.jobTitle) ? data.jobTitle : "",
  };
}

// Risolve con `fallback` se la promise non si chiude entro `ms` (anti-hang).
function ure_withTimeout(promise, ms, fallback) {
  return new Promise(function (resolve) {
    var done = false;
    var timer = setTimeout(function () {
      if (!done) { done = true; resolve(fallback); }
    }, ms);
    promise.then(
      function (v) { if (!done) { done = true; clearTimeout(timer); resolve(v); } },
      function () { if (!done) { done = true; clearTimeout(timer); resolve(fallback); } }
    );
  });
}

// Versione "safe": non lancia e non si blocca MAI.
// - try/catch protegge dai reject; ure_withTimeout protegge dagli HANG di MSAL/Graph
//   nel runtime event-based headless (causa primaria di "nessuna firma" per tutti).
// - Worst case: dopo 3s prosegue con titolo vuoto e la firma viene comunque inserita.
async function ure_getProfileSafe(email) {
  var empty = { displayName: "", title: "" };
  try {
    if (!ure_isValid(email)) return empty;
    return await ure_withTimeout(ure_getProfile(email), 3000, empty);
  } catch (e) {
    try { console.log("UreTech: Graph profile fallback: " + e); } catch (x) {}
    return empty;
  }
}

// From (displayName + email). Promise che non rifiuta mai.
function ure_getFrom() {
  return new Promise(function (resolve) {
    try {
      var item = Office.context.mailbox.item;
      if (item && item.from && typeof item.from.getAsync === "function") {
        item.from.getAsync(function (res) {
          if (res && res.status === "succeeded" && res.value) {
            resolve({ displayName: res.value.displayName || "", email: res.value.emailAddress || "" });
          } else {
            var p = Office.context.mailbox.userProfile;
            resolve({ displayName: (p && p.displayName) || "", email: (p && p.emailAddress) || "" });
          }
        });
        return;
      }
    } catch (e) {}
    var pp = Office.context.mailbox.userProfile;
    resolve({ displayName: (pp && pp.displayName) || "", email: (pp && pp.emailAddress) || "" });
  });
}

// HTML -> testo semplice (per l'inserimento negli APPUNTAMENTI "text-only", es. Outlook web).
function ure_htmlToText(html) {
  return String(html)
    .replace(/<\s*br\s*\/?>/gi, "\n")
    .replace(/<\/\s*(p|div|tr|li|h[1-6]|table)\s*>/gi, "\n")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&middot;/gi, "·")
    .replace(/&raquo;/gi, "»")
    .replace(/[ \t]+/g, " ")
    .replace(/[ \t]*\n[ \t]*/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

// Inserisce la firma nell'item scegliendo l'API GIUSTA (doc MS "Get or set the body"):
// - MESSAGGIO: `setSignatureAsync` (API solo-messaggio, posiziona sotto la risposta).
// - APPUNTAMENTO: NIENTE setSignatureAsync. `getTypeAsync` OBBLIGATORIO prima di inserire, poi
//   `prependAsync` con coercion COERENTE: su Outlook web il corpo può risultare "text" e inserire
//   HTML con coercion Html dà "L'operazione non è supportata" (era il bug degli appuntamenti).
//   -> se html inserisco l'HTML, se text inserisco la versione testo (tag rimossi). `done` SEMPRE.
function ure_insertSignature(sig, done) {
  try {
    var item = Office.context.mailbox.item;
    var body = item && item.body;
    if (!body) { done(); return; }
    // Detection AFFIDABILE via itemType: su un appuntamento `setSignatureAsync` ESISTE come funzione
    // (ma è solo-messaggio → runtime "operazione non supportata"), quindi NON basta il typeof.
    var isAppointment = item.itemType === "appointment";
    var useSetSignature = !isAppointment && typeof body.setSignatureAsync === "function";
    var onDone = function (api, r) {
      try {
        if (!r || r.status !== "succeeded") {
          // Fail-open silenzioso: il relay server-side è la rete di sicurezza. Log con l'API usata.
          try { console.log("UreTech: firma KO [" + api + "]: " + (r && r.error && r.error.message)); } catch (x) {}
        } else {
          try { console.log("UreTech: firma OK [" + api + "] itemType=" + item.itemType); } catch (x) {}
        }
      } catch (e) {}
      done();
    };
    if (useSetSignature) {
      body.setSignatureAsync(sig, { coercionType: "html" }, function (r) { onDone("setSignature", r); });
    } else {
      // Appuntamento (o messaggio senza setSignatureAsync): getTypeAsync PRIMA, poi prependAsync con
      // coercion coerente (html->HTML, text->testo). Su Outlook web il corpo può risultare "text".
      body.getTypeAsync(function (t) {
        if (!t || t.status !== "succeeded") {
          try { console.log("UreTech: getType KO: " + (t && t.error && t.error.message)); } catch (x) {}
          done();
          return;
        }
        var asHtml = t.value === "html";
        body.prependAsync(
          asHtml ? sig : ure_htmlToText(sig),
          { coercionType: asHtml ? "html" : "text" },
          function (r) { onDone("prepend/" + (asHtml ? "html" : "text"), r); }
        );
      });
    }
  } catch (e) {
    try { console.log("UreTech: insert error: " + e); } catch (x) {}
    done();
  }
}

// Applica la firma. event.completed() viene SEMPRE chiamato (bulletproof).
async function ure_applySignature(event) {
  try {
    var info = await ure_getFrom();
    // Graph è la fonte PRIMARIA del nome (corretto anche per le condivise) + del titolo.
    // Fallback morbido: se Graph non risponde, usa il displayName di from.getAsync.
    var prof = await ure_getProfileSafe(info.email);
    var name = ure_isValid(prof.displayName) ? prof.displayName : info.displayName;
    var sig = ure_buildSignature(name, info.email, prof.title);
    ure_insertSignature(sig, function () { try { event.completed(); } catch (x) {} });
  } catch (e) {
    try { console.log("UreTech: apply error: " + e); } catch (x) {}
    try { event.completed(); } catch (x) {}
  }
}

// OnNewMessageCompose (nuove, risposte, inoltri).
function checkSignature(event) {
  var item = Office.context.mailbox.item;
  if (item && typeof item.disableClientSignatureAsync === "function") {
    item.disableClientSignatureAsync(function () { ure_applySignature(event); });
  } else {
    ure_applySignature(event);
  }
}

// OnMessageFromChanged: riapplica la firma quando cambia il From (caselle condivise).
function onFromChanged(event) {
  ure_applySignature(event);
}

Office.onReady(function () {});
Office.actions.associate("checkSignature", checkSignature);
Office.actions.associate("onFromChanged", onFromChanged);
